#include <stdio.h>

int main(void)
{
    int n = 6;
    int x = n++;
    printf("%d %d\n", x, n);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 6;
    int x = --n;
    printf("%d %d\n", x, n);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int n = 2;
    n++;
    ++n;
    printf("%d\n", n);
    return 0;
}

